    const display = normalizeTagName(name);
    const key = tagKey(name);
    if (!key) return null;
    const existing = db.prepare('SELECT id FROM tags WHERE norm_key = ?').get(key);
    if (existing) return existing.id;
    const info = db
      .prepare('INSERT INTO tags (name, norm_key) VALUES (?, ?)')
      .run(display, key);
    return info.lastInsertRowid;
  }

