    getById(id) {
      const row = db.prepare('SELECT * FROM bookmarks WHERE id = ?').get(id);
      return shape(row);
    },

    getByUrl(url) {
      const row = db.prepare('SELECT * FROM bookmarks WHERE url = ?').get(url);
      return shape(row);
