3	// --- URL normalization / validation (FR-002, FR-003) ---
4	
5	export function normalizeUrl(input) {
6	  if (input == null) throw new ValidationError('An address is required');
7	  let raw = String(input).trim();
8	  if (!raw) throw new ValidationError('An address is required');
9	  // Assume https:// when no scheme is provided (FR-003).
10	  if (!/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\//.test(raw)) {
11	    raw = 'https://' + raw;
12	  }
13	  let parsed;
14	  try {
15	    parsed = new URL(raw);
16	  } catch {
17	    throw new ValidationError('That address is not a valid web link');
18	  }
19	  if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
20	    throw new ValidationError('Only http and https addresses are supported');
21	  }
22	  if (!parsed.hostname || !parsed.hostname.includes('.')) {
23	    throw new ValidationError('That address is not a valid web link');
24	  }
25	  return parsed.href;
26	}
27	
28	export class ValidationError extends Error {}
29	export class ConflictError extends Error {
30	  constructor(message, existingId) {
31	    super(message);
32	    this.existingId = existingId;
33	  }
34	}
35	export class NotFoundError extends Error {}
36	
37	// --- Tag normalization (FR-015) ---
38	
39	export function normalizeTagName(name) {
40	  return String(name ?? '').trim();
41	}
42	export function tagKey(name) {
43	  return normalizeTagName(name).toLowerCase();
44	}
45	
46	// --- Data access layer ---
47	
48	export function createStore(db, { collect = collectMetadata } = {}) {
49	  const now = () => new Date().toISOString();
50	
51	  // Cache prepared statements: reused across calls (better perf) and, being
52	  // strongly referenced for the store's lifetime, they are finalized cleanly by
53	  // db.close() rather than churned and GC-collected during process teardown.
54	  const stmtCache = new Map();
55	  const prep = (sql) => {
56	    let s = stmtCache.get(sql);
57	    if (!s) {
58	      s = db.prepare(sql);
59	      stmtCache.set(sql, s);
60	    }
61	    return s;
62	  };
63	
64	  function tagsForBookmark(id) {
65	    return prep(
66	        `SELECT t.name FROM tags t
67	         JOIN bookmark_tags bt ON bt.tag_id = t.id
68	         WHERE bt.bookmark_id = ?
69	         ORDER BY t.name COLLATE NOCASE`
70	      )
71	      .all(id)
72	      .map((r) => r.name);
73	  }
74	
75	  function shape(row) {
76	    if (!row) return null;
77	    return {
78	      id: row.id,
79	      url: row.url,
80	      title: row.title,
81	      description: row.description,
82	      faviconUrl: row.favicon_url,
83	      tags: tagsForBookmark(row.id),
84	      createdAt: row.created_at,
85	      updatedAt: row.updated_at,
86	    };
87	  }
88	
89	  function upsertTag(name) {
90	    const display = normalizeTagName(name);
91	    const key = tagKey(name);
92	    if (!key) return null;
93	    const existing = prep('SELECT id FROM tags WHERE norm_key = ?').get(key);
94	    if (existing) return existing.id;
95	    const info = prep('INSERT INTO tags (name, norm_key) VALUES (?, ?)')
96	      .run(display, key);
97	    return info.lastInsertRowid;
98	  }
99	
100	  function setTags(bookmarkId, names) {
101	    prep('DELETE FROM bookmark_tags WHERE bookmark_id = ?').run(bookmarkId);
102	    if (!Array.isArray(names)) return;
103	    const seen = new Set();
104	    const link = prep(
105	      'INSERT OR IGNORE INTO bookmark_tags (bookmark_id, tag_id) VALUES (?, ?)'
106	    );
107	    for (const name of names) {
108	      const key = tagKey(name);
109	      if (!key || seen.has(key)) continue;
110	      seen.add(key);
111	      const tagId = upsertTag(name);
112	      if (tagId) link.run(bookmarkId, tagId);
113	    }
114	  }
115	
116	  const store = {
117	    getById(id) {
118	      const row = prep('SELECT * FROM bookmarks WHERE id = ?').get(id);
119	      return shape(row);
120	    },
121	
122	    getByUrl(url) {
123	      const row = prep('SELECT * FROM bookmarks WHERE url = ?').get(url);
124	      return shape(row);
125	    },
126	
