// Custom test runner: runs all unit + integration test files in a single
// process (isolation: 'none') and force-exits with the correct code.
//
// Why: better-sqlite3 on this Node version can abort during process teardown
// ("Assertion failed: (env) != nullptr" in Statement::~Statement) after all
// tests have already passed and reported. Running in one process and calling
// process.exit() as soon as the run completes exits before that native
// teardown path executes, so a green run reports green deterministically.
import { run } from 'node:test';
import { spec } from 'node:test/reporters';
import { glob } from 'node:fs/promises';

const files = [];
for (const pattern of ['tests/unit/**/*.test.js', 'tests/integration/**/*.test.js']) {
  for await (const f of glob(pattern)) files.push(f);
}

let failed = false;
const stream = run({ files, isolation: 'none', concurrency: false });
stream.on('test:fail', () => {
  failed = true;
});
stream.compose(spec).pipe(process.stdout);
stream.on('end', () => {
  process.exit(failed ? 1 : 0);
});

